'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ICONS = {
  leaf:'M19 4C9 3 4 6 4 12a7 7 0 0 0 12 5c3-3 3-8 3-13ZM4 20 15 9M8 16v-5m0 5h5',
  search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  plus:'M12 5v14M5 12h14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',
  arrow:'M4 12h15m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',
  clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5l8-3Zm-4 10 3 3 5-6',
  pin:'M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  filter:'M4 6h16M7 12h10M10 18h4',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v10M7 4l10 6',
  grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7',
  clipboard:'M9 4H6a2 2 0 0 0-2 2v14h16V6a2 2 0 0 0-2-2h-3M9 2h6v5H9V2ZM8 12h8M8 16h5',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 3a4 4 0 0 1 0 8m1 4a4 4 0 0 1 4 4v2',
  chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',log:'M6 3h12v18H6V3Zm3 5h6m-6 4h6m-6 4h4',
  image:'M3 3h18v18H3V3Zm0 13 6-6 5 5 3-3 4 4M16 7h.01',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',close:'m6 6 12 12M6 18 18 6',logout:'M9 4H4v16h5m5-12 4 4-4 4m-6-4h10'
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name] || ICONS.box}"/></svg>`;
const statusLabels = {published:'已发布',reserved:'已预约',pending:'待审核',rejected:'已驳回',offline:'已下架',sold:'已售出',draft:'草稿',waiting:'待卖家确认',accepted:'已确认待交接',completed:'已完成',cancelled:'已取消',expired:'已超时',declined:'已拒绝'};
const statusColor = s => ['published','completed'].includes(s)?'green':['waiting','pending','reserved'].includes(s)?'amber':['rejected','offline','cancelled','declined'].includes(s)?'red':['accepted'].includes(s)?'purple':'';
const tag = (s,label) => `<span class="tag ${statusColor(s)}">${esc(label||statusLabels[s]||s)}</span>`;
const btn = (label,action,kind='',extra='') => `<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const money = n => Number(n).toLocaleString('zh-CN');
const BASE_PRODUCTS = [
  {id:'camera',title:'轻便微单相机 · 带原装镜头',price:1580,condition:9,category:'数码电子',photo:'camera',status:'published',seller:'林同学',owner:'seller',place:'仙林校区 · 仙I公共区域',desc:'陪我记录了两年的校园生活。机身和镜头保存完好，功能正常，附原装电池、充电器和肩带。可以面交检查后再确认。',time:'2小时前',version:1},
  {id:'headphones',title:'头戴式耳机 · 通勤学习都合适',price:260,condition:8,category:'数码电子',photo:'headphones',status:'published',seller:'许同学',owner:'other',place:'鼓楼校区 · 图书馆门口',desc:'耳机功能正常，耳罩已清洁。附收纳袋，欢迎面交检查。',time:'3小时前',version:1},
  {id:'books',title:'阅读书单 · 一组闲置好书',price:58,condition:8,category:'图书教材',photo:'books',status:'published',seller:'陈同学',owner:'other',place:'仙林校区 · 图书馆公共区域',desc:'整理书架时留下的好书，内页干净，少量阅读痕迹。整组转让，期待它们遇见新的读者。',time:'5小时前',version:1},
  {id:'backpack',title:'日常通勤双肩包 · 轻便耐用',price:80,condition:9,category:'生活用品',photo:'backpack',status:'reserved',seller:'林同学',owner:'seller',place:'仙林校区 · 图书馆公共区域',desc:'闲置双肩包，容量适合日常上课，拉链和肩带完好。已清洗，欢迎线下查看。',time:'昨天',version:1},
  {id:'review-book',title:'闲置书籍 · 阅读收藏',price:36,condition:8,category:'图书教材',photo:'books',status:'pending',seller:'张同学',owner:'other',place:'仙林校区 · 公共区域',desc:'几本阅读完的书，书页完整，没有缺页。希望转给喜欢阅读的同学。',time:'10分钟前',version:2},
  {id:'draft',title:'我的闲置相机配件',price:120,condition:8,category:'数码电子',photo:'camera',status:'draft',seller:'林同学',owner:'seller',place:'',desc:'',time:'昨天',version:1},
  {id:'rejected-book',title:'整理转让的阅读书籍',price:42,condition:7,category:'图书教材',photo:'books',status:'rejected',seller:'林同学',owner:'seller',place:'仙林校区',desc:'书籍内页完好。',reason:'请补充书籍内页照片，并说明是否有笔记或划线。',time:'昨天',version:1},
  {id:'offline-headphone',title:'备用耳机 · 已暂停转让',price:180,condition:8,category:'数码电子',photo:'headphones',status:'offline',seller:'林同学',owner:'seller',place:'鼓楼校区',desc:'备用耳机，目前暂停转让。',blocked:false,time:'前天',version:1}
];
function initialState(){return {role:'buyer',logged:true,products:structuredClone(BASE_PRODUCTS),reservations:[{id:'R20261111001',productId:'backpack',status:'accepted',buyer:'周同学',seller:'林同学',buyerConfirmed:false,sellerConfirmed:false,created:'2026-11-11 10:20',accepted:'2026-11-11 10:32',expiresAt:Date.now()+86400000,contact:'演示联系信息已由双方授权',contacts:{buyer:'buyer-demo@example.invalid',seller:'seller-demo@example.invalid'},snapshot:{title:BASE_PRODUCTS[3].title,price:80}}],selectedReservation:'R20261111001',notices:[{title:'卖家已接受你的预约',text:'“日常通勤双肩包”的预约已确认，可以与卖家约定面交。',time:'今天 10:32',read:false,target:'transaction',reservationId:'R20261111001'},{title:'校园面交小提醒',text:'建议在校内公共区域交接，检查商品后再确认收货。',time:'今天 10:20',read:true}],audit:[{action:'接受预约',object:'R20261111001',actor:'林同学',result:'成功',time:'11-11 10:32'},{action:'创建预约',object:'R20261111001',actor:'周同学',result:'成功',time:'11-11 10:20'},{action:'审核通过',object:'camera',actor:'管理员',result:'成功',time:'11-11 09:40'}],q:'',category:'全部闲置',sort:'newest',filters:false,min:'',max:'',condition:'',publicStatus:'',tab:'active',userDisabled:false,reviewId:'review-book',editId:'draft',notificationsRead:false};}
let state;
try{state=JSON.parse(localStorage.getItem('qiwu-lab2-v1'))||initialState();}catch{state=initialState();}
const save=()=>{try{localStorage.setItem('qiwu-lab2-v1',JSON.stringify(state));}catch{}};
const product=id=>state.products.find(p=>p.id===id);
const currentReservation=()=>state.reservations.find(r=>r.id===state.selectedReservation)||state.reservations[0];
const activeReservation=r=>['waiting','accepted'].includes(r.status);
const route=()=>location.hash.slice(1)||'market';
function go(path){if(route()===path)render();else location.hash=path;window.scrollTo(0,0);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function log(action,object,result='成功'){state.audit.unshift({action,object,actor:state.role==='admin'?'管理员':state.role==='seller'?'林同学':'周同学',result,time:'11-11 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});}
function notify(title,text,target='my-products',reservationId=null){state.notices.unshift({title,text,target,reservationId,time:'刚刚',read:false});}
function brand(){return `<a class="brand" href="#market"><span class="brand-mark">${icon('leaf')}</span><span>栖物<small>QIWU · CAMPUS</small></span></a>`;}
function header(admin=false){const r=route();return `<header class="topbar"><div class="top-inner">${brand()}${admin?'<span class="tag purple">管理工作台</span>':`<nav class="top-nav" aria-label="主导航"><a href="#market" class="${r.startsWith('market')||r.startsWith('product-')?'active':''}">发现闲置</a><a href="#transactions" class="${r.startsWith('transaction')?'active':''}">交易中心</a><a href="#my-products" class="${r==='my-products'||r==='publish'?'active':''}">我的发布</a></nav>`}<div class="top-actions">${admin?'<a class="small muted" href="#market">返回商品大厅</a>':`<button class="icon-button" data-action="notifications" aria-label="系统通知">${icon('bell')}${state.notices.some(n=>!n.read)?'<span class="dot"></span>':''}</button><a href="#publish" class="btn primary small">${icon('plus')}发布闲置</a>`}<a class="user" href="#${admin?'admin-users':'login'}"><span class="avatar">${admin?'管':state.role==='seller'?'林':'周'}</span><span class="small">${admin?'管理员':state.role==='seller'?'林同学':'周同学'}</span></a></div></div></header>`;}
function footer(){return `<footer class="footer"><div>栖物 · 让闲置在校园继续发光 <span class="prototype-notice">　课程交互原型 · 演示数据</span></div><div class="demo-switch"><a href="#guide">设计规范</a><a href="#register">注册流程</a><button class="link tiny" data-action="role-buyer">买家视角</button><button class="link tiny" data-action="role-seller">卖家视角</button><a href="#admin-overview">管理端</a><button class="link tiny" data-action="reset">重置演示</button></div></footer>`;}
function shell(content){return header()+`<main class="page">${content}</main>`+footer();}
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function empty(title,sub,action=''){return `<div class="empty"><div class="empty-icon">${icon('box')}</div><h2>${title}</h2><p>${sub}</p>${action}</div>`;}
function card(p){return `<a class="product-card" href="#product-${p.id}"><div class="product-cover"><img src="assets/${p.photo}.jpg" alt="${esc(p.title)}"><span class="cover-tag ${p.status==='reserved'?'reserved':''}">${p.status==='reserved'?'已被预约':p.condition+'成新'}</span></div><div class="product-info"><h3>${esc(p.title)}</h3><div class="product-meta"><span>${esc(p.category)}</span><span>·</span><span>${esc(p.place.split(' · ')[0]||'校内面交')}</span></div><div class="price"><small>¥</small>${money(p.price)}</div><div class="product-foot"><span class="row"><span class="avatar">${p.seller[0]}</span>${esc(p.seller)}</span><span>${p.time}</span></div></div></a>`;}
function market(){let list=state.products.filter(p=>['published','reserved'].includes(p.status));if(state.q)list=list.filter(p=>p.title.includes(state.q));if(state.category!=='全部闲置')list=list.filter(p=>p.category===state.category);if(state.min!=='')list=list.filter(p=>p.price>=+state.min);if(state.max!=='')list=list.filter(p=>p.price<=+state.max);if(state.condition)list=list.filter(p=>p.condition===+state.condition);if(state.publicStatus)list=list.filter(p=>p.status===state.publicStatus);if(state.sort==='price-up')list.sort((a,b)=>a.price-b.price);if(state.sort==='price-down')list.sort((a,b)=>b.price-a.price);return shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow">A SECOND LIFE, ON CAMPUS</div><h1>闲置有去处，<br>校园有新遇。</h1><p>从一本好书到一台相机，让喜欢的物品继续被珍惜。</p></div><div class="hero-art"><img src="assets/books.jpg" class="second" alt="书籍"><img src="assets/camera.jpg" alt="闲置相机"><div class="hero-ticket">${icon('leaf')}校内面交，让转让更简单</div></div></section><form id="search-form" class="searchbar">${icon('search')}<input name="q" type="search" aria-label="搜索闲置商品" placeholder="搜一搜你需要的闲置，比如相机、教材、耳机" value="${esc(state.q)}"><button class="btn primary" type="submit">搜索</button></form><section class="market-tools"><div class="categories">${['全部闲置','数码电子','图书教材','生活用品','运动户外'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-action="category" data-value="${c}">${c}</button>`).join('')}<button class="filter-trigger" data-action="filters">${icon('filter')}更多筛选</button></div>${state.filters?`<form id="filter-form" class="filters"><label>最低价格<input type="number" name="min" min="0" value="${state.min}" placeholder="不限"></label><label>最高价格<input type="number" name="max" min="0" value="${state.max}" placeholder="不限"></label><label>新旧程度<select name="condition"><option value="">全部</option>${[9,8,7,6,5,4,3,2,1].map(n=>`<option value="${n}" ${+state.condition===n?'selected':''}>${n}成新</option>`).join('')}</select></label><label>商品状态<select name="status"><option value="">公开商品</option><option value="published" ${state.publicStatus==='published'?'selected':''}>已发布</option><option value="reserved" ${state.publicStatus==='reserved'?'selected':''}>已预约</option></select></label><button class="btn small primary" type="submit">应用</button><button class="link small" data-action="clear-filters" type="button">清空筛选</button></form>`:''}</section><div class="list-head"><h2>${state.q?'搜索结果':'刚刚上新'} <span class="muted small" style="font-weight:400;margin-left:10px">${list.length} 件闲置</span></h2><div class="sorts">${[['newest','最新发布'],['price-up','价格从低到高'],['price-down','价格从高到低']].map(([v,l])=>`<button class="${state.sort===v?'active':''}" data-action="sort" data-value="${v}">${l}</button>`).join('')}</div></div>${list.length?`<section class="product-grid">${list.map(card).join('')}</section>`:`<div class="panel">${empty('暂时没有找到合适的闲置','试试更换关键词，或放宽筛选条件。',btn('清空筛选','clear-filters','primary'))}</div>`}<div class="tip-strip"><span class="row">${icon('shield')}校园邮箱验证 · 平台人工审核</span><span class="row">${icon('pin')}线上预约，校内线下面交</span><span class="row">${icon('check')}双方确认后，交易才算完成</span></div>`);}
function detail(id){const p=product(id);if(!p)return shell(empty('商品不存在','请返回商品大厅查看。','<a href="#market" class="btn primary">返回大厅</a>'));const own=state.role==='seller'&&p.owner==='seller';const unavailable=p.status!=='published';return shell(`<div class="breadcrumb"><a href="#market">发现闲置</a><span>／</span><span>${esc(p.category)}</span><span>／</span><span>商品详情</span></div><section class="panel detail-grid"><div><img class="detail-photo" src="assets/${p.photo}.jpg" alt="${esc(p.title)}"><div class="thumbs"><img src="assets/${p.photo}.jpg" alt="商品图片缩略图"></div><div class="small muted" style="margin-top:12px">商品示意图 · 线下面交时请检查实物</div></div><div class="detail-text">${tag(p.status)} <span class="tag">${p.condition}成新</span><h1>${esc(p.title)}</h1><p class="muted small">${esc(p.category)} · ${p.time}发布</p><div class="price"><small>¥</small>${money(p.price)}</div><div class="row"><span class="avatar">${p.seller[0]}</span><strong>${esc(p.seller)}</strong><span class="tag green">校园邮箱已验证</span></div><dl class="facts"><dt>新旧程度</dt><dd>${p.condition}成新</dd><dt>面交地点</dt><dd>${esc(p.place||'由双方预约确认后约定')}</dd><dt>交易方式</dt><dd>线上预约 · 线下交接</dd></dl><div class="notice">${icon('info')}预约后卖家有24小时确认。卖家接受后，双方再约定面交。</div><div class="detail-actions">${own?'<a class="btn soft" href="#my-products">这是你的商品 · 管理发布</a>':unavailable?`<button class="btn" disabled>${p.status==='reserved'?'已被预约，暂不可预约':'当前状态不可预约'}</button>`:btn('预约这件闲置 '+icon('arrow'),'reserve','primary',`data-id="${p.id}"`)}</div><p class="tiny muted">平台不提供在线支付。请检查商品后，再在交易中心确认完成。</p></div></section><section class="panel pad" style="margin-top:24px"><h2 style="margin-bottom:14px">关于这件闲置</h2><p class="text-block">${esc(p.desc)}</p></section>`);}
function tradeSteps(r){const stages=['预约成功','卖家确认','线下面交','双方完成'];const current=r.status==='waiting'?1:r.status==='completed'?4:2;return `<div class="steps">${stages.map((s,i)=>`<div class="step ${i<current?'done':i===current?'current':''}"><i>${i<current?'✓':i+1}</i>${s}</div>`).join('')}</div>`;}
function transaction(){const r=currentReservation();if(!r)return shell(empty('还没有预约','找到喜欢的闲置后，可以在这里查看交易进度。','<a href="#market" class="btn primary">去逛逛</a>'));const p=product(r.productId);const seller=state.role==='seller';const completed=r.status==='completed';const active=activeReservation(r);const mineConfirmed=seller?r.sellerConfirmed:r.buyerConfirmed;let title=statusLabels[r.status],desc='',action='';if(r.status==='waiting'){title='预约成功，等待卖家确认';desc=`请在 ${new Date(r.expiresAt).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})} 前处理，超时将自动释放商品。`;action=seller?btn('接受预约','accept','primary full')+`<div style="height:10px"></div>`+btn('拒绝预约','decline','full'):btn('取消预约','cancel','full');}else if(r.status==='accepted'){title=mineConfirmed?'你已确认，等待对方完成':'预约已确认，准备线下面交';desc=mineConfirmed?'双方都确认后，交易才会正式完成。':'请先联系对方，检查商品并完成线下交接。';action=mineConfirmed?'<button class="btn soft full" disabled>你已完成确认</button>':btn(seller?'确认交易完成':'确认收货','confirm-trade','primary full');if(!seller)action+=`<div style="text-align:center;margin-top:15px"><button class="link small muted" data-action="cancel">取消预约</button></div>`;}else{title=completed?'交易完成，感谢让闲置继续发光':`预约${statusLabels[r.status].replace('已','')}`;desc=completed?'双方确认均已记录，可以在交易历史中回看。':(r.reason||'这条预约已经结束，商品以当前展示状态为准。');action='<a href="#transactions" class="btn full">返回交易中心</a>';}
return shell(head('交易详情',`预约编号 ${esc(r.id)} · ${seller?'卖家':'买家'}视角`,'<a href="#transactions" class="btn">返回列表</a>')+`<div class="trade-grid"><div class="stack"><section class="panel pad"><div class="trade-status"><div class="status-icon">${icon(completed?'check':active?'clock':'info')}</div><div><h2>${title}</h2><p class="muted small" style="margin-top:4px">${desc}</p></div></div>${active||completed?tradeSteps(r):''}<div class="trade-product"><img src="assets/${p.photo}.jpg" alt="${esc(p.title)}"><div style="flex:1"><h3>${esc(r.snapshot.title)}</h3><p class="muted small">${p.condition}成新 · ${esc(p.category)}</p><div class="price"><small>¥</small>${money(r.snapshot.price)}</div></div>${tag(r.status)}</div><dl class="summary-grid"><div><dt>买家</dt><dd>${esc(r.buyer)}</dd></div><div><dt>卖家</dt><dd>${esc(r.seller)}</dd></div><div><dt>预约时间</dt><dd>${r.created}</dd></div><div><dt>面交地点</dt><dd>${esc(p.place)}</dd></div></dl></section><section class="panel pad"><div class="section-head"><h2>进度记录</h2><span class="tiny muted">按实际发生顺序记录</span></div><div class="timeline">${completed?'<div class="event">双方均已确认，交易完成<time>刚刚</time></div>':''}${r.buyerConfirmed?'<div class="event">买家确认收货<time>本次演示操作</time></div>':''}${r.sellerConfirmed?'<div class="event">卖家确认交易完成<time>本次演示操作</time></div>':''}${!active&&!completed?`<div class="event">${esc(r.reason||statusLabels[r.status])}<time>本次演示操作</time></div>`:''}${r.accepted?`<div class="event">卖家已接受预约<time>${r.accepted}</time></div>`:''}<div class="event">买家提交预约，商品已保留<time>${r.created}</time></div></div></section></div><div class="stack"><section class="panel pad"><div class="eyebrow">NEXT STEP</div><h2>${completed?'本次交易已完成':active?(seller?'卖家待办':'买家待办'):'预约已结束'}</h2><p class="muted small" style="margin:10px 0 20px">${r.status==='waiting'?(seller?'查看商品与预约信息后，选择接受或拒绝。':'等待卖家接受预约，也可以主动取消。'):active?'完成线下交接后，再确认你的这一步。':'历史记录保留，终止后的联系信息不再展示。'}</p>${action}${r.status==='accepted'||completed?`<hr class="divider"><div class="confirm-card"><span class="small">买家确认收货</span>${tag(r.buyerConfirmed?'completed':'waiting',r.buyerConfirmed?'已确认':'待确认')}</div><div class="confirm-card"><span class="small">卖家确认完成</span>${tag(r.sellerConfirmed?'completed':'waiting',r.sellerConfirmed?'已确认':'待确认')}</div>`:''}</section><section class="panel pad"><div class="section-head"><h3>面交联系</h3>${icon('shield')}</div>${r.status==='accepted'?`<p class="small muted" style="margin-bottom:14px">仅当前预约双方可见，预约结束后隐藏并清除。</p><div class="notice">${icon('mail')}对方已授权的校内联系方式<br>${esc(r.contacts?.[seller?'buyer':'seller']||'对方尚未填写联系方式')}</div><button class="link small" data-action="edit-contact" style="margin-top:14px">填写 / 更新我的授权联系方式</button><p class="tiny muted" style="margin-top:10px">此处为原型演示信息，不可用于实际联系。</p>`:`<p class="small muted">${r.status==='waiting'?'卖家接受预约后，显示双方主动提供的联系信息。':'本次预约的联系信息已不可见。'}</p>`}</section><div class="notice">${icon('pin')}建议在校园公共区域面交，确认物品情况后再完成交易。</div></div></div>`);}
function transactions(){const list=state.reservations.filter(r=>state.tab==='history'?!activeReservation(r):activeReservation(r));return shell(head('交易中心','每一次交接，都有清晰的进度。')+`<div class="tabs"><button data-action="trade-tab" data-value="active" class="${state.tab==='active'?'active':''}">进行中 <span class="count">${state.reservations.filter(activeReservation).length}</span></button><button data-action="trade-tab" data-value="history" class="${state.tab==='history'?'active':''}">历史交易</button><span class="small muted" style="margin-left:auto;padding:12px">当前：${state.role==='seller'?'我卖出的':'我买入的'}</span></div><section class="panel">${list.length?list.map(r=>{const p=product(r.productId);return `<div class="list-item"><img src="assets/${p.photo}.jpg" alt="${esc(p.title)}"><div class="grow"><h3>${esc(r.snapshot.title)}</h3><p class="small muted">${state.role==='seller'?'买家 '+r.buyer:'卖家 '+r.seller} · ${r.created}</p><div style="margin-top:8px">${tag(r.status)}</div></div><div class="price"><small>¥</small>${money(r.snapshot.price)}</div>${btn('查看进度','open-trade','small',`data-id="${r.id}"`)}</div>`;}).join(''):empty('这里还没有交易记录','可以先去商品大厅看看喜欢的闲置。','<a class="btn primary" href="#market">发现闲置</a>')}</section>`);}
function myProducts(){const list=state.products.filter(p=>p.owner==='seller');return shell(head('我的发布','管理闲置、查看审核结果，处理每一份预约。','<a href="#publish" class="btn primary">'+icon('plus')+'发布闲置</a>')+`<div class="tabs"><button class="active">全部发布 <span class="count">${list.length}</span></button><span class="small muted" style="margin-left:auto;padding:12px">商品状态随审核与预约同步更新</span></div><section class="panel">${list.map(p=>`<div class="list-item"><img src="assets/${p.photo}.jpg" alt="${esc(p.title)}"><div class="grow"><h3>${esc(p.title)}</h3><p class="small muted">${esc(p.category)} · ${p.condition}成新</p>${p.reason?`<p class="small" style="color:var(--red);margin-top:6px">${esc(p.reason)}</p>`:''}<div style="margin-top:8px">${tag(p.status)} ${p.blocked?'<span class="tag red">重审受限</span>':''}</div></div><div class="price"><small>¥</small>${money(p.price)}</div><div class="stack" style="gap:8px">${['draft','rejected','published'].includes(p.status)?btn(p.status==='draft'?'继续编辑':p.status==='rejected'?'修改后重审':'编辑商品','edit-product','small',`data-id="${p.id}"`):p.status==='offline'?btn(p.blocked?'重审受限':'重新提交审核','edit-product','small',`data-id="${p.id}" ${p.blocked?'disabled':''}`):p.status==='reserved'?btn('查看预约','find-product-trade','small',`data-id="${p.id}"`):''}${['published','reserved'].includes(p.status)?btn('下架商品','offline','small',`data-id="${p.id}"`):''}</div></div>`).join('')}</section><div class="notice" style="margin-top:20px">${icon('info')}已发布商品修改重要信息后需要重新审核；已预约商品暂不能修改。主动下架的商品可以重新提交审核。</div>`);}
function publish(){const p=product(state.editId)||product('draft');return shell(head(p.status==='rejected'?'根据审核意见修改':'发布一件闲置','认真介绍它，帮助下一位同学作出选择。','<a href="#my-products" class="btn">我的发布</a>')+`<form id="publish-form"><div class="form-layout"><div class="stack">${p.reason?`<div class="notice warning">${icon('info')}审核意见：${esc(p.reason)}</div>`:''}<section class="panel pad"><div class="form-title"><span>01</span><h2>商品信息</h2></div><div class="field"><label for="p-title">商品名称<em>*</em></label><input id="p-title" name="title" type="text" maxlength="60" value="${p.id==='draft'?'':esc(p.title)}" placeholder="简洁说明品类、型号或特点"><div class="hint">例如：轻便微单相机，带原装镜头</div></div><div class="grid2"><div class="field"><label for="p-category">商品分类<em>*</em></label><select id="p-category" name="category">${['数码电子','图书教材','生活用品','运动户外'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="p-condition">新旧程度<em>*</em></label><select id="p-condition" name="condition">${[9,8,7,6,5,4,3,2,1].map(n=>`<option value="${n}" ${p.condition===n?'selected':''}>${n}成新</option>`).join('')}</select></div></div><div class="field"><label for="p-price">转让价格（元）<em>*</em></label><input id="p-price" name="price" type="number" min="0.01" step="0.01" value="${p.id==='draft'?'':p.price}" placeholder="请输入大于0的价格"></div><div class="field"><label for="p-desc">商品描述<em>*</em></label><textarea id="p-desc" name="description" placeholder="介绍使用情况、配件，以及需要提前说明的瑕疵。">${p.id==='draft'?'':esc(p.desc)}</textarea></div></section><section class="panel pad"><div class="form-title"><span>02</span><h2>图片与面交</h2></div><div class="field"><label>商品图片<em>*</em></label><div class="upload"><img class="upload-preview" id="upload-preview" src="assets/${p.photo}.jpg" alt="示例商品图片"><label class="upload-box" for="photo-input">${icon('plus')}添加图片</label><input type="file" id="photo-input" accept="image/jpeg,image/png,image/webp" hidden></div><div class="hint">至少1张，最多9张；JPG、PNG或WebP，单张不超过5MB。当前为演示示意图。</div></div><div class="field"><label for="p-place">建议面交地点 <span class="muted tiny">选填</span></label><input id="p-place" name="place" type="text" value="${esc(p.place)}" placeholder="建议填写校园公共区域，不填写宿舍门牌等私人位置"><div class="hint">具体时间和地点可在预约确认后与对方约定。</div></div></section><div id="publish-errors" role="alert"></div><div class="form-actions"><p class="small muted">草稿仅自己可见；审核通过后公开。</p><div class="row"><button class="btn" type="button" data-action="save-draft">保存草稿</button><button class="btn primary" type="submit">提交审核 ${icon('arrow')}</button></div></div></div><aside class="stack"><section class="panel pad"><h3 style="margin-bottom:18px">发布预览</h3><div class="preview-mini"><img src="assets/${p.photo}.jpg" alt="商品卡片预览"><div><h3 id="preview-title">${p.id==='draft'?'你的闲置商品':esc(p.title)}</h3><span class="small muted">${esc(p.category)} · ${p.condition}成新</span><p class="price" id="preview-price"><small>¥</small>${p.id==='draft'?'—':money(p.price)}</p></div></div></section><section class="panel pad"><h3 style="margin-bottom:12px">让介绍更有帮助</h3><p class="text-block small">拍清商品全貌与瑕疵。<br>说明功能、配件和使用情况。<br>价格与实际物品保持一致。</p><hr class="divider"><p class="small muted">提交后由管理员人工审核，审核结果会通过站内通知告诉你。</p></section></aside></div></form>`);}
function notifications(){return shell(head('消息中心','审核、预约与交易的重要变化，都在这里。',btn('全部标为已读','read-all',''))+`<section class="panel">${state.notices.map((n,index)=>`<div class="notification ${n.read?'':'unread'}"><div class="status-icon">${icon(n.title.includes('审核')?'clipboard':'bell')}</div><div><h3>${esc(n.title)} ${n.read?'':'<span class="tag purple">未读</span>'}</h3><p>${esc(n.text)}</p><time>${n.time}</time></div><button class="link" data-action="open-notice" data-index="${index}">${n.target?'查看详情':'标为已读'} ${icon('chevron')}</button></div>`).join('')}</section>`);}
function auth(register){return shell(`<section class="auth"><div class="auth-story"><div><div class="eyebrow">GOOD THINGS DESERVE ANOTHER STORY</div><h1>你的闲置，<br>是别人的刚刚好。</h1><p class="muted" style="margin-top:14px">在校园，让值得珍惜的物品继续流转。</p><img src="assets/camera.jpg" alt="闲置相机"></div><div class="row small muted">${icon('shield')}校园邮箱验证 · 校内线下面交</div></div><div class="auth-form"><h2>${register?'加入栖物':'欢迎回来'}</h2><p class="intro">${register?'一个校园账号，同时拥有买家与卖家身份。':'登录后继续发现闲置、查看预约与管理发布。'}</p><form id="${register?'register':'login'}-form" novalidate><div class="field"><label for="auth-email">南京大学邮箱</label><input id="auth-email" type="email" name="email" placeholder="你的邮箱@nju.edu.cn" autocomplete="username"><div class="hint">仅支持 @nju.edu.cn 邮箱</div></div>${register?`<div class="field"><label for="auth-code">邮箱验证码</label><div class="row"><input id="auth-code" name="code" type="text" placeholder="6位验证码" maxlength="6" style="min-width:0"><button class="btn small" data-action="send-code" type="button">获取验证码</button></div><div class="hint" id="code-hint">验证码用于确认邮箱由你本人使用。</div></div><div class="field"><label for="auth-name">昵称</label><input id="auth-name" name="name" type="text" placeholder="其他同学如何称呼你" maxlength="20"></div>`:''}<div class="field"><label for="auth-password">${register?'设置密码':'密码'}</label><input id="auth-password" type="password" name="password" placeholder="${register?'至少8位，包含字母与数字':'请输入密码'}" autocomplete="${register?'new-password':'current-password'}"></div>${register?'<p class="small muted" style="margin-bottom:18px">注册邮箱不会默认向其他用户公开。</p>':''}<div id="auth-errors" class="field-error" role="alert" style="margin-bottom:14px"></div><button class="btn primary full" type="submit">${register?'验证并注册':'登录'}</button></form><p class="auth-foot">${register?'已有账号？ <a class="link" href="#login">去登录</a>':'还没有账号？ <a class="link" href="#register">注册校园账号</a>'}</p><p class="tiny muted" style="margin-top:25px">此为交互演示，不会发送真实邮件或创建真实账号。</p></div></section>`);}
function adminShell(content){const current=route();const links=[['admin-overview','chart','工作台概览'],['admin-review','clipboard','商品审核'],['admin-products','box','商品管理'],['admin-users','users','用户管理'],['admin-audit','log','操作日志']];return header(true)+`<div class="admin-layout"><aside class="sidebar"><div class="side-label">ADMIN WORKSPACE</div>${links.map(([r,i,l])=>`<a class="${current===r?'active':''}" href="#${r}">${icon(i)}${l}${r==='admin-review'?`<span class="count">${state.products.filter(p=>p.status==='pending').length}</span>`:''}</a>`).join('')}<div class="side-note">每次处理都留下依据，<br>让校园交易更有秩序。</div></aside><main class="admin-main">${content}<div class="prototype-notice" style="margin-top:24px">课程交互原型 · 演示数据　<a href="#market">返回用户端</a>　<button class="link tiny" data-action="reset">重置演示</button></div></main></div>`;}
function overview(){const stats=[['商品总数',state.products.length,'包含各生命周期状态','box'],['待审核',state.products.filter(p=>p.status==='pending').length,'等待人工审核','clipboard'],['有效预约',state.products.filter(p=>p.status==='reserved').length,'已占用的商品','clock'],['完成交易',state.reservations.filter(r=>r.status==='completed').length,'双方确认后的交易','check']];const cats=['数码电子','图书教材','生活用品','运动户外'];return adminShell(head('工作台概览','校园闲置与交易的当前情况。','<span class="tag">统计口径：当前保存记录</span>')+`<section class="stats">${stats.map(([l,n,s,i])=>`<div class="panel stat"><div class="stat-label">${l}${icon(i)}</div><strong>${n}</strong><p class="small muted">${s}</p></div>`).join('')}</section><div class="grid2"><section class="panel pad"><div class="section-head"><h2>商品分类分布</h2><span class="small muted">单位：件</span></div><div class="bars">${cats.map(c=>{const n=state.products.filter(p=>p.category===c).length;return `<div class="bar-row"><span>${c}</span><div class="bar-track"><div class="bar-fill" style="width:${n/state.products.length*100}%"></div></div><strong>${n}</strong></div>`;}).join('')}</div></section><section class="panel pad"><div class="section-head"><h2>商品状态概览</h2><a href="#admin-products" class="link small">查看明细</a></div><div class="bars">${['published','reserved','pending','draft','rejected','offline','sold'].map(s=>{const n=state.products.filter(p=>p.status===s).length;return `<div class="bar-row"><span>${statusLabels[s]}</span><div class="bar-track"><div class="bar-fill" style="width:${n/state.products.length*100}%;background:${s==='reserved'?'#c3a369':'#8c6cb7'}"></div></div><strong>${n}</strong></div>`;}).join('')}</div></section></div><section class="panel" style="margin-top:24px"><div class="table-top"><h2>最近操作</h2><a href="#admin-audit" class="link small">全部日志 →</a></div>${auditTable(state.audit.slice(0,4))}</section>`);}
function review(){const list=state.products.filter(p=>p.status==='pending');let p=product(state.reviewId);if(!p||p.status!=='pending')p=list[0];if(p)state.reviewId=p.id;return adminShell(head('商品审核','核对商品信息，给每一次发布明确的结果。',`<span class="tag amber">${list.length} 件待处理</span>`)+(p?`<div class="review-grid"><section class="panel review-list"><div class="review-list-head">待审核队列</div>${list.map(q=>`<div class="review-item ${p.id===q.id?'selected':''}" data-action="select-review" data-id="${q.id}" tabindex="0" role="button"><img src="assets/${q.photo}.jpg" alt="${esc(q.title)}"><div><h3>${esc(q.title)}</h3><p>${esc(q.seller)} · ¥${q.price}</p><p>${q.time}提交</p></div></div>`).join('')}<p class="review-note" style="padding:0 18px 18px">仅处理当前仍处于待审核状态的商品。</p></section><section class="panel review-details"><div class="section-head"><div><span class="eyebrow">PRODUCT REVIEW</span><h2 style="margin-top:6px">${esc(p.title)}</h2></div>${tag(p.status)}</div><div class="review-media"><img src="assets/${p.photo}.jpg" alt="待审核商品"><dl class="facts"><dt>发布者</dt><dd>${esc(p.seller)} <span class="tag green">校园验证</span></dd><dt>分类</dt><dd>${esc(p.category)}</dd><dt>价格</dt><dd><strong>¥ ${money(p.price)}</strong></dd><dt>成色</dt><dd>${p.condition}成新</dd><dt>面交</dt><dd>${esc(p.place||'未填写')}</dd></dl></div><h3 style="margin-bottom:8px">商品描述</h3><p class="text-block">${esc(p.desc)}</p><hr class="divider"><h3 style="margin-bottom:12px">审核要点</h3><div class="row small muted" style="flex-wrap:wrap;gap:18px"><span class="row">${icon('image')}图片与描述一致</span><span class="row">${icon('shield')}内容合法合规</span><span class="row">${icon('check')}必要信息完整</span></div><div class="field" style="margin-top:22px"><label for="review-reason">审核说明 <span class="muted tiny">驳回时必填</span></label><textarea id="review-reason" placeholder="指出需要修改的具体信息，帮助卖家一次修正。" style="min-height:80px"></textarea><div class="row" style="margin-top:8px"><button class="chip small" data-action="reason-preset" data-value="请补充商品实拍细节，确认图片与描述一致。">图片不清晰</button><button class="chip small" data-action="reason-preset" data-value="请补充商品功能、配件及瑕疵情况。">信息不完整</button></div></div><div class="row between"><span class="tiny muted">审核决定与操作者将记入日志。</span><div class="row">${btn('驳回并说明','reject-review','',`data-id="${p.id}"`)}${btn(icon('check')+'审核通过','approve-review','primary',`data-id="${p.id}"`)}</div></div></section></div>`:`<section class="panel">${empty('待审核商品已处理完','新的提交会出现在这里。','<a href="#admin-products" class="btn">查看全部商品</a>')}</section>`));}
function adminProducts(){return adminShell(head('商品管理','查看商品状态，处理违规内容与重审限制。')+`<section class="panel"><div class="table-top"><h3>全部商品 <span class="count">${state.products.length}</span></h3><input type="search" id="admin-product-search" class="input" placeholder="筛选商品名称" aria-label="筛选商品名称"></div><div class="table-wrap"><table><thead><tr><th>商品</th><th>卖家</th><th>价格</th><th>状态</th><th>管理操作</th></tr></thead><tbody>${state.products.map(p=>`<tr data-search="${esc(p.title)}"><td><div class="row"><img src="assets/${p.photo}.jpg" alt=""><span>${esc(p.title)}</span></div></td><td>${p.seller}</td><td>¥${money(p.price)}</td><td>${tag(p.status)} ${p.blocked?'<span class="tag red">重审受限</span>':''}</td><td>${['published','reserved'].includes(p.status)?btn('违规下架','admin-offline','small danger',`data-id="${p.id}"`):p.blocked?btn('解除重审限制','unblock','small',`data-id="${p.id}"`):'<span class="tiny muted">—</span>'}</td></tr>`).join('')}</tbody></table></div></section>`);}
function adminUsers(){const count=state.reservations.filter(activeReservation).length;return adminShell(head('用户管理','账号停用前先核对关联影响，所有处理保留记录。')+`<div class="notice warning" style="margin-bottom:22px">${icon('info')}停用将使现有会话失效，并按确认的影响范围处理商品和有效预约；已完成交易保留。</div><section class="panel table-wrap"><table><thead><tr><th>用户</th><th>角色</th><th>账号状态</th><th>关联业务</th><th>操作</th></tr></thead><tbody><tr><td><div class="row"><span class="avatar">林</span><div>林同学<p class="tiny muted">校园邮箱已验证</p></div></div></td><td>普通用户 · 买卖双身份</td><td>${tag(state.userDisabled?'offline':'published',state.userDisabled?'已停用':'正常')}</td><td>${state.products.filter(p=>p.owner==='seller'&&['published','reserved'].includes(p.status)).length} 件公开商品 / ${count} 条有效预约</td><td>${btn(state.userDisabled?'恢复账号':'停用账号','toggle-user',state.userDisabled?'small':'small danger')}</td></tr><tr><td><div class="row"><span class="avatar">周</span><div>周同学<p class="tiny muted">校园邮箱已验证</p></div></div></td><td>普通用户 · 买卖双身份</td><td>${tag('published','正常')}</td><td>原型中的买家账号</td><td><span class="tiny muted">演示只开放林同学账号的管理操作</span></td></tr></tbody></table></section>`);}
function auditTable(list){return `<div class="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>操作</th><th>业务对象</th><th>结果</th></tr></thead><tbody>${list.map(a=>`<tr><td>${esc(a.time)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.object)}</td><td>${tag(a.result==='成功'?'published':'rejected',a.result)}</td></tr>`).join('')}</tbody></table></div>`;}
function audit(){return adminShell(head('操作日志','关键业务的成功与失败结果均可追溯。')+`<section class="panel"><div class="table-top"><h3>审计记录</h3><span class="tiny muted">只读查看 · 不提供编辑或删除</span></div>${auditTable(state.audit)}</section><p class="small muted" style="margin-top:16px">日志不包含密码、验证码或面交联系信息。所有业务时间以服务端记录为准。</p>`);}
function guide(){return shell(head('视觉与交互规范','栖物 QIWU · 清晰、有序、适度留白')+`<div class="stack"><section class="panel pad"><div class="eyebrow">01 / COLOR & TYPE</div><h2 style="margin-bottom:20px">让内容成为主角</h2><div class="style-swatches"><div class="swatch" style="background:#6746a4;color:white">品牌紫 #6746A4</div><div class="swatch" style="background:#242333;color:white">正文 #242333</div><div class="swatch" style="background:#f7f7fa">页面 #F7F7FA</div><div class="swatch" style="background:#f0ebf8">淡紫 #F0EBF8</div></div><hr class="divider"><h1>清楚的标题，简洁的说明。</h1><p class="muted" style="margin-top:12px">页面标题30px / 区块标题20px / 正文15–16px / 辅助信息12–13px。保持足够对比，状态不用颜色单独表达。</p></section><section class="panel pad"><div class="eyebrow">02 / COMPONENTS</div><h2 style="margin-bottom:20px">一致的动作与反馈</h2><div class="row">${btn('主要操作','noop','primary')}${btn('次要操作','noop')}${btn('轻量操作','noop','soft')}${btn('有影响的操作','noop','danger')}<button class="btn" disabled>暂不可用</button></div><div class="row" style="margin-top:24px">${['published','reserved','pending','rejected','accepted','completed'].map(s=>tag(s)).join('')}</div><div class="notice" style="margin-top:24px">${icon('info')}信息说明放在相关操作附近，必要时展开，不挤占主要内容。</div></section><section class="panel pad"><div class="eyebrow">03 / INFORMATION HIERARCHY</div><h2>先告诉用户下一步，再解释细节</h2><p class="text-block" style="margin-top:12px">交易页先展示当前状态和下一操作者；重要操作说明后果；历史和规则放在下方。商品列表保留图片、标题、价格、成色和状态；完整介绍进入详情后查看。</p></section></div>`);}
function render(){let r=route();if(r.startsWith('admin-'))state.role='admin';else if(['publish','my-products'].includes(r))state.role='seller';const views={market,transactions,transaction,publish,'my-products':myProducts,notifications,login:()=>auth(false),register:()=>auth(true),'admin-overview':overview,'admin-review':review,'admin-products':adminProducts,'admin-users':adminUsers,'admin-audit':audit,guide};$('#app').innerHTML=r.startsWith('product-')?detail(r.slice(8)):(views[r]||market)();document.title=(r.startsWith('admin-')?'栖物管理工作台':'栖物 · 校园闲置好去处');save();}
let modalCallback=null;
function modal(title,body,confirm,callback,danger=false){modalCallback=callback;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2>${body}<div class="actions">${btn('暂不操作','modal-close')}${btn(confirm,'modal-confirm',danger?'danger':'primary')}</div></section></div>`;setTimeout(()=>$('.modal .actions button')?.focus(),0);}
function closeModal(){$('#modal-root').innerHTML='';modalCallback=null;}
function endReservation(r,reason,status='cancelled'){if(!activeReservation(r))return false;r.status=status;r.reason=reason;r.contact=null;r.contacts={};const p=product(r.productId);if(p.status==='reserved')p.status='published';notify('预约已结束',`${r.snapshot.title}：${reason}`,'transaction',r.id);log(statusLabels[status],r.id);return true;}
function unpublish(p,reason,blocked=false){if(!['published','reserved'].includes(p.status))return false;for(const r of state.reservations.filter(r=>r.productId===p.id&&activeReservation(r)))endReservation(r,reason);p.status='offline';p.blocked=blocked;p.reason=reason;p.version++;notify('商品已下架',`${p.title}：${reason}`);log('商品下架',p.id);return true;}
function saveDraft(submit){const form=$('#publish-form');const data=new FormData(form);let errors=[];const title=String(data.get('title')).trim(),price=Number(data.get('price')),desc=String(data.get('description')).trim();if(submit){if(!title)errors.push('请填写商品名称。');if(!price||price<=0)errors.push('请输入大于0的价格。');if(!desc)errors.push('请填写商品描述。');}if(errors.length){$('#publish-errors').innerHTML=`<div class="notice error">${icon('info')}<div>${errors.join('<br>')}</div></div>`;$('#publish-errors').scrollIntoView({block:'center',behavior:'smooth'});return;}let p=product(state.editId);if(!p){p={id:'draft-'+Date.now(),owner:'seller',seller:'林同学',photo:'camera',version:1};state.products.push(p);}if(['reserved','sold'].includes(p.status)){toast('当前商品状态不允许修改');return;}Object.assign(p,{title:title||'未命名草稿',price:price||0,desc,category:String(data.get('category')),condition:+data.get('condition'),place:String(data.get('place')),status:submit?'pending':'draft',time:'刚刚',reason:'',version:p.version+1});state.role='seller';log(submit?'提交审核':'保存草稿',p.id);if(submit)notify('商品已提交审核',`${p.title} 已进入审核队列，结果会在这里通知你。`);save();go('my-products');toast(submit?'已提交审核，暂不公开展示':'草稿已保存，仅自己可见');}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id,value=target.dataset.value;
  if(action==='modal-close'){closeModal();return;}if(action==='modal-confirm'){if(modalCallback)modalCallback();return;}
  if(action==='edit-contact'){const r=currentReservation(),key=state.role==='seller'?'seller':'buyer';if(r.status!=='accepted'){toast('只有已确认的有效预约可以设置联系信息');return;}modal('授权本次面交联系信息','<p>仅本次预约的另一方可见，预约终止后清除。此原型只使用演示信息，请勿输入真实联系方式。</p><div class="field"><label for="handover-value">演示联系方式</label><input id="handover-value" class="input" maxlength="100" placeholder="例如 demo@example.invalid" value="'+esc(r.contacts?.[key]||'')+'"></div><label class="checkline"><input id="handover-consent" type="checkbox">我同意仅向本次预约的另一方展示这条信息</label>','授权并保存',()=>{const value=$('#handover-value').value.trim();if(!value||!$('#handover-consent').checked){toast('请填写演示信息并勾选授权');return;}r.contacts=r.contacts||{};r.contacts[key]=value;save();closeModal();render();toast('本次预约的联系信息已更新');});return;}
  if(action==='open-notice'){const n=state.notices[+target.dataset.index];n.read=true;if(n.reservationId)state.selectedReservation=n.reservationId;save();if(n.target)go(n.target);else{render();toast('消息已标为已读');}return;}
  if(action==='notifications'){go('notifications');return;}if(action==='noop')return;
  if(action==='role-buyer'||action==='role-seller'){state.role=action==='role-buyer'?'buyer':'seller';save();go('market');toast(state.role==='buyer'?'已切换为买家演示视角':'已切换为卖家演示视角');return;}
  if(action==='reset'){state=initialState();save();go('market');toast('演示数据已重置');return;}
  if(action==='filters'){state.filters=!state.filters;render();return;}
  if(action==='category'){state.category=value;render();return;}
  if(action==='sort'){state.sort=value;render();return;}
  if(action==='clear-filters'){Object.assign(state,{q:'',category:'全部闲置',min:'',max:'',condition:'',publicStatus:''});render();return;}
  if(action==='trade-tab'){state.tab=value;render();return;}
  if(action==='read-all'){state.notices.forEach(n=>n.read=true);render();toast('全部消息已标为已读');return;}
  if(action==='open-trade'){state.selectedReservation=id;go('transaction');return;}
  if(action==='find-product-trade'){const r=state.reservations.find(r=>r.productId===id&&activeReservation(r));if(r){state.selectedReservation=r.id;go('transaction');}else toast('此商品暂无当前演示账号可查看的预约');return;}
  if(action==='edit-product'){state.editId=id;state.role='seller';go('publish');return;}
  if(action==='save-draft'){saveDraft(false);return;}
  if(action==='reserve'){const p=product(id);modal('预约这件闲置？',`<p>${esc(p.title)} · ¥${money(p.price)}</p><div class="notice">预约成功后暂时保留商品，卖家须在24小时内处理。你可在交易完成前取消预约。</div>`,'确认预约',()=>{if(p.status!=='published'||state.userDisabled||(state.role==='seller'&&p.owner==='seller')){log('创建预约',id,'失败');closeModal();render();toast('商品状态或当前权限已变化，请查看最新信息');return;}const existing=state.reservations.find(r=>r.productId===id&&activeReservation(r));if(existing){state.selectedReservation=existing.id;closeModal();go('transaction');return;}const r={id:'R'+Date.now(),productId:id,status:'waiting',buyer:'周同学',seller:p.seller,buyerConfirmed:false,sellerConfirmed:false,created:'2026-11-11 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),expiresAt:Date.now()+86400000,snapshot:{title:p.title,price:p.price}};state.reservations.unshift(r);p.status='reserved';state.selectedReservation=r.id;state.role='buyer';log('创建预约',r.id);notify('预约已提交',`${p.title}：等待卖家确认。`,'transaction',r.id);save();closeModal();go('transaction');toast('预约成功，商品已为你保留');});return;}
  if(action==='accept'){const r=currentReservation();if(state.role!=='seller'||r.status!=='waiting'){toast('当前状态或身份不能接受预约');return;}if(Date.now()>=r.expiresAt){endReservation(r,'超过24小时未确认','expired');render();toast('预约已超时');return;}r.status='accepted';r.accepted='2026-11-11 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});r.contact='演示授权联系信息';notify('卖家已接受预约',r.snapshot.title+'：可以约定面交了。','transaction',r.id);log('接受预约',r.id);render();toast('已接受预约，请与买家约定面交');return;}
  if(action==='cancel'||action==='decline'){const r=currentReservation();modal(action==='decline'?'拒绝这条预约？':'取消这条预约？',`<p>${action==='decline'?'拒绝后将通知买家并释放商品。':'取消后将结束当前预约并通知对方；若商品仍可售，将重新允许预约。'}</p>`,'确认'+(action==='decline'?'拒绝':'取消'),()=>{if(!activeReservation(r)||(action==='decline'&&(state.role!=='seller'||r.status!=='waiting'))||(action==='cancel'&&state.role!=='buyer')){toast('预约状态或权限已变化');closeModal();return;}endReservation(r,action==='decline'?'卖家拒绝了预约':'买家主动取消预约',action==='decline'?'declined':'cancelled');save();closeModal();render();toast('预约已结束');},true);return;}
  if(action==='confirm-trade'){const r=currentReservation();const seller=state.role==='seller';modal(seller?'确认已经完成交接？':'确认已经收到商品？','<p>请在实际线下交接完成后确认。双方均确认后，商品将标记为已售出。</p>',seller?'确认交易完成':'确认收货',()=>{if(r.status!=='accepted'){closeModal();toast('当前预约状态不允许确认');return;}if(seller)r.sellerConfirmed=true;else r.buyerConfirmed=true;if(r.buyerConfirmed&&r.sellerConfirmed){r.status='completed';r.contact=null;r.contacts={};product(r.productId).status='sold';log('交易完成',r.id);notify('交易已完成',r.snapshot.title+'：双方都已确认完成。','transaction',r.id);}else log(seller?'卖家确认完成':'买家确认收货',r.id);save();closeModal();render();toast(r.status==='completed'?'双方均已确认，交易完成':'你的确认已记录，等待另一方');});return;}
  if(action==='offline'||action==='admin-offline'){const p=product(id),admin=action==='admin-offline';modal(admin?'违规下架商品':'下架这件闲置？',`<p>${esc(p.title)}。${p.status==='reserved'?'当前存在有效预约，下架会同时取消预约并通知买家。':'下架后商品不再公开展示或接受预约。'}</p>${admin?'<div class="field"><label for="offline-reason">处理原因（必填）</label><textarea id="offline-reason" placeholder="说明违规事实与需要整改的内容"></textarea></div>':'<div class="notice">主动下架后，可编辑商品并重新提交审核。</div>'}`,'确认下架',()=>{const reason=admin?$('#offline-reason').value.trim():'卖家主动下架';if(!reason){toast('请填写处理原因');return;}if(!unpublish(p,reason,admin)){toast('商品状态已变化');closeModal();render();return;}save();closeModal();render();toast('商品已下架，关联预约与通知已同步处理');},true);return;}
  if(action==='unblock'){const p=product(id);modal('解除重新审核限制？','<p>仅解除重审限制，商品仍保持已下架。卖家需要重新提交并通过审核，才能恢复公开。</p>','解除限制',()=>{p.blocked=false;log('解除重审限制',p.id);save();closeModal();render();toast('已解除限制，商品仍待卖家重新提交');});return;}
  if(action==='select-review'){state.reviewId=id;render();return;}
  if(action==='reason-preset'){$('#review-reason').value=value;return;}
  if(action==='approve-review'||action==='reject-review'){const p=product(id),reason=$('#review-reason').value.trim();if(p.status!=='pending'){log('商品审核',id,'失败');render();toast('商品已被处理，请查看最新状态');return;}if(action==='reject-review'&&!reason){toast('请先填写具体驳回原因');$('#review-reason').focus();return;}p.status=action==='approve-review'?'published':'rejected';p.reason=reason;notify(p.status==='published'?'商品审核通过':'商品被驳回',p.title+'：'+(reason||'商品已公开展示。'));log(p.status==='published'?'审核通过':'审核驳回',p.id);render();toast(p.status==='published'?'审核通过，商品已公开':'已驳回，原因已通知卖家');return;}
  if(action==='toggle-user'){if(state.userDisabled){state.userDisabled=false;log('恢复账号','林同学');render();toast('账号已恢复，商品不会自动重新上架');return;}const impacted=state.products.filter(p=>p.owner==='seller'&&['published','reserved'].includes(p.status));modal('停用账号并处理关联业务？',`<p>将停用林同学的账号并使会话失效，下架其 ${impacted.length} 件公开商品，取消关联有效预约并通知对方。已完成交易与历史记录保留。</p><div class="field"><label for="disable-reason">停用原因（必填）</label><textarea id="disable-reason" placeholder="请记录本次处理依据"></textarea></div>`,'确认停用',()=>{const reason=$('#disable-reason').value.trim();if(!reason){toast('请填写停用原因');return;}state.userDisabled=true;impacted.forEach(p=>unpublish(p,'账号停用：'+reason,true));log('停用账号','林同学');save();closeModal();render();toast('账号已停用，关联业务已处理');},true);return;}
  if(action==='send-code'){const email=$('#auth-email').value.trim();if(!/^[^\s@]+@nju\.edu\.cn$/i.test(email)){$('#auth-errors').textContent='请输入有效的 @nju.edu.cn 校园邮箱。';return;}$('#auth-errors').textContent='';$('#code-hint').textContent='演示验证码：123456（仅本地原型，不发送邮件）';toast('已生成本地演示验证码');return;}
});
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target;if(f.id==='search-form'){state.q=new FormData(f).get('q').trim();render();}else if(f.id==='filter-form'){const d=new FormData(f);if(d.get('min')!==''&&d.get('max')!==''&&+d.get('min')>+d.get('max')){toast('最低价格不能高于最高价格');return;}Object.assign(state,{min:d.get('min'),max:d.get('max'),condition:d.get('condition'),publicStatus:d.get('status')});render();}else if(f.id==='publish-form'){saveDraft(true);}else if(['register-form','login-form'].includes(f.id)){const d=new FormData(f),register=f.id==='register-form';let error='';if(!/^[^\s@]+@nju\.edu\.cn$/i.test(d.get('email')))error='请使用 @nju.edu.cn 校园邮箱。';else if(register&&d.get('code')!=='123456')error='验证码不正确，请核对后重试。';else if(register&&!d.get('name').trim())error='请填写昵称。';else if(register&&(!/[A-Za-z]/.test(d.get('password'))||!/[0-9]/.test(d.get('password'))||d.get('password').length<8))error='密码需至少8位，并包含字母和数字。';else if(!d.get('password'))error='请输入密码。';else if(state.userDisabled&&state.role==='seller')error='账号已停用，无法继续登录。';if(error){$('#auth-errors').textContent=error;return;}state.logged=true;state.role='buyer';save();go('market');toast(register?'演示注册完成，欢迎加入栖物':'已进入登录演示');}});
document.addEventListener('input',event=>{if(event.target.id==='p-title')$('#preview-title').textContent=event.target.value||'你的闲置商品';if(event.target.id==='p-price')$('#preview-price').innerHTML='<small>¥</small>'+money(event.target.value||0);if(event.target.id==='admin-product-search'){const q=event.target.value;document.querySelectorAll('tr[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(q));}});
document.addEventListener('change',event=>{if(event.target.id==='photo-input'){const f=event.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('请选择5MB以内的JPG、PNG或WebP图片');return;}$('#upload-preview').src=URL.createObjectURL(f);toast('图片已加入本次预览');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Enter'&&event.target.matches('[role="button"][data-action]'))event.target.click();});
window.addEventListener('hashchange',render);
window.qiwu={getState:()=>structuredClone(state),reset:()=>{state=initialState();save();render();},setRole:role=>{state.role=role;save();render();},expireDue:now=>{let n=0;for(const r of state.reservations){if(r.status==='waiting'&&now>=r.expiresAt){endReservation(r,'超过24小时未确认','expired');n++;}}save();render();return n;}};
render();
